=== FILE: apb_gpio.v ===
`default_nettype none

// apb_gpio: APB4 GPIO peripheral with interrupts.
// Implements interface_spec.md per microarchitecture.md (zero wait states,
// 32-bit registers masked by PINS, combinational detection, W1C status).
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0..N-1 set: the pins that exist.
    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // ------------------------------------------------------------------
    // APB decode
    // ------------------------------------------------------------------
    wire       access   = psel && penable;
    wire [3:0] index    = paddr[5:2];
    wire       mapped   = (paddr[1:0] == 2'b00) &&
                          !(|paddr[ADDR_WIDTH-1:6]) &&
                          (index <= IDX_INTR_STATUS);
    wire       ro_write = pwrite && (index == IDX_DATA_IN);
    wire       wr_en    = access && pwrite && mapped && !ro_write;
    wire       rd_en    = access && !pwrite && mapped;

    assign pready  = 1'b1;
    assign pslverr = access && (!mapped || ro_write);

    // Write mask: byte strobes expanded to 32 bits, restricted to the pins.
    wire [31:0] strb_bits = {{8{pstrb[3]}}, {8{pstrb[2]}},
                             {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wmask     = strb_bits & PINS;

    // gpio_in widened to 32 bits with zeros above N.
    wire [31:0] in_w;
    genvar g;
    generate
        for (g = 0; g < 32; g = g + 1) begin : g_in
            if (g < N) begin : g_pin
                assign in_w[g] = gpio_in[g];
            end else begin : g_none
                assign in_w[g] = 1'b0;
            end
        end
    endgenerate

    // ------------------------------------------------------------------
    // Registers
    // ------------------------------------------------------------------
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] in_q;
    reg [31:0] in_prev;
    reg [31:0] rise_en_q;
    reg [31:0] fall_en_q;
    reg [31:0] high_en_q;
    reg [31:0] low_en_q;
    reg [31:0] intr_en_q;
    reg [31:0] status_q;

    function [31:0] merge;
        input [31:0] f_old;
        input [31:0] f_data;
        input [31:0] f_mask;
        begin
            merge = (f_old & ~f_mask) | (f_data & f_mask);
        end
    endfunction

    // ------------------------------------------------------------------
    // Detection and status
    // ------------------------------------------------------------------
    wire [31:0] rise     = in_q & ~in_prev;
    wire [31:0] fall     = ~in_q & in_prev;
    wire [31:0] detected = ((rise & rise_en_q) | (fall & fall_en_q) |
                            (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
    wire [31:0] clear    = (wr_en && (index == IDX_INTR_STATUS)) ?
                           (pwdata & wmask) : 32'd0;
    // Detection is ORed last: a detection beats a clear.
    wire [31:0] status_next = (status_q & ~clear) | detected;

    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            in_q       <= 32'd0;
            in_prev    <= 32'd0;
            rise_en_q  <= 32'd0;
            fall_en_q  <= 32'd0;
            high_en_q  <= 32'd0;
            low_en_q   <= 32'd0;
            intr_en_q  <= 32'd0;
            status_q   <= 32'd0;
        end else begin
            in_q     <= in_w;
            in_prev  <= in_q;
            status_q <= status_next;
            if (wr_en) begin
                case (index)
                    IDX_DATA_OUT:    data_out_q <= merge(data_out_q, pwdata, wmask);
                    IDX_DIR:         dir_q      <= merge(dir_q,      pwdata, wmask);
                    IDX_INTR_RISE:   rise_en_q  <= merge(rise_en_q,  pwdata, wmask);
                    IDX_INTR_FALL:   fall_en_q  <= merge(fall_en_q,  pwdata, wmask);
                    IDX_INTR_HIGH:   high_en_q  <= merge(high_en_q,  pwdata, wmask);
                    IDX_INTR_LOW:    low_en_q   <= merge(low_en_q,   pwdata, wmask);
                    IDX_INTR_ENABLE: intr_en_q  <= merge(intr_en_q,  pwdata, wmask);
                    default: ;
                endcase
            end
        end
    end

    // ------------------------------------------------------------------
    // Read data
    // ------------------------------------------------------------------
    reg [31:0] rdata_mux;
    always @* begin
        case (index)
            IDX_DATA_OUT:    rdata_mux = data_out_q;
            IDX_DIR:         rdata_mux = dir_q;
            IDX_DATA_IN:     rdata_mux = in_q;
            IDX_INTR_RISE:   rdata_mux = rise_en_q;
            IDX_INTR_FALL:   rdata_mux = fall_en_q;
            IDX_INTR_HIGH:   rdata_mux = high_en_q;
            IDX_INTR_LOW:    rdata_mux = low_en_q;
            IDX_INTR_ENABLE: rdata_mux = intr_en_q;
            IDX_INTR_STATUS: rdata_mux = status_q;
            default:         rdata_mux = 32'd0;
        endcase
    end

    assign prdata   = rd_en ? rdata_mux : 32'd0;
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & intr_en_q);

`ifdef FORMAL
    // Design-intent assertions.
    reg f_reset_seen;
    initial f_reset_seen = 1'b0;
    always @(posedge pclk) begin
        if (!presetn) f_reset_seen <= 1'b1;
    end

    always @* begin
        assert (pready == 1'b1);
        if (!access) begin
            assert (prdata == 32'd0);
            assert (pslverr == 1'b0);
        end
        if (f_reset_seen) begin
            assert ((data_out_q & ~PINS) == 32'd0);
            assert ((dir_q      & ~PINS) == 32'd0);
            assert ((in_q       & ~PINS) == 32'd0);
            assert ((in_prev    & ~PINS) == 32'd0);
            assert ((rise_en_q  & ~PINS) == 32'd0);
            assert ((fall_en_q  & ~PINS) == 32'd0);
            assert ((high_en_q  & ~PINS) == 32'd0);
            assert ((low_en_q   & ~PINS) == 32'd0);
            assert ((intr_en_q  & ~PINS) == 32'd0);
            assert ((status_q   & ~PINS) == 32'd0);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
