`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for apb_gpio. Three lanes (N = 32, 8, 1) share one
// APB bus; every register is per pin with zeros above N, so each lane's
// expected value is the N = 32 expectation masked to its pins (irq excepted).
module apb_gpio_tb;

    localparam [7:0] A_DATA_OUT = 8'h00;
    localparam [7:0] A_DIR      = 8'h04;
    localparam [7:0] A_DATA_IN  = 8'h08;
    localparam [7:0] A_RISE     = 8'h0C;
    localparam [7:0] A_FALL     = 8'h10;
    localparam [7:0] A_HIGH     = 8'h14;
    localparam [7:0] A_LOW      = 8'h18;
    localparam [7:0] A_EN       = 8'h1C;
    localparam [7:0] A_STAT     = 8'h20;

    reg         clk;
    reg         rstn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gin;

    wire [31:0] rd32;
    wire [31:0] rd8;
    wire [31:0] rd1;
    wire        rdy32, rdy8, rdy1;
    wire        err32, err8, err1;
    wire        irq32, irq8, irq1;
    wire [31:0] out32, oe32;
    wire [7:0]  out8, oe8;
    wire [0:0]  out1, oe1;

    integer passed;
    integer failed;
    integer stepno;
    reg [8*64-1:0] nonce;

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) u_n32 (
        .pclk(clk), .presetn(rstn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(rd32), .pready(rdy32), .pslverr(err32),
        .gpio_in(gin), .gpio_out(out32), .gpio_oe(oe32), .irq(irq32));

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) u_n8 (
        .pclk(clk), .presetn(rstn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(rd8), .pready(rdy8), .pslverr(err8),
        .gpio_in(gin[7:0]), .gpio_out(out8), .gpio_oe(oe8), .irq(irq8));

    apb_gpio #(.ADDR_WIDTH(8), .N(1)) u_n1 (
        .pclk(clk), .presetn(rstn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(rd1), .pready(rdy1), .pslverr(err1),
        .gpio_in(gin[0:0]), .gpio_out(out1), .gpio_oe(oe1), .irq(irq1));

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // ------------------------------------------------------------------
    // Checking helpers
    // ------------------------------------------------------------------
    task chk(input [31:0] got, input [31:0] exp);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("step %0d: check failed: got %h, expected %h", stepno, got, exp);
            end
        end
    endtask

    task chk_bus(input [31:0] exp);
        begin
            chk(rd32, exp);
            chk(rd8,  exp & 32'h0000_00FF);
            chk(rd1,  exp & 32'h0000_0001);
        end
    endtask

    task chk_err(input e);
        begin
            chk({29'd0, err32, err8, err1}, {29'd0, e, e, e});
        end
    endtask

    task chk_rdy;
        begin
            chk({29'd0, rdy32, rdy8, rdy1}, 32'd7);
        end
    endtask

    task chk_irq(input e32, input e8, input e1);
        begin
            chk({29'd0, irq32, irq8, irq1}, {29'd0, e32, e8, e1});
        end
    endtask

    task chk_pins(input [31:0] eout, input [31:0] eoe);
        begin
            chk(out32, eout);
            chk({24'd0, out8}, eout & 32'h0000_00FF);
            chk({31'd0, out1}, eout & 32'h0000_0001);
            chk(oe32, eoe);
            chk({24'd0, oe8}, eoe & 32'h0000_00FF);
            chk({31'd0, oe1}, eoe & 32'h0000_0001);
        end
    endtask

    // ------------------------------------------------------------------
    // APB transfer: setup at a falling edge, access at the next, idle after.
    // If chg is set, gin is driven to pins together with the setup phase.
    // ------------------------------------------------------------------
    task xfer(input wr, input [7:0] a, input [31:0] d, input [3:0] s,
              input chg, input [31:0] pins, input [31:0] erd, input eerr);
        begin
            stepno = stepno + 1;
            @(negedge clk);
            if (chg) gin = pins;
            paddr   = a;
            pwrite  = wr;
            pwdata  = wr ? d : 32'd0;
            pstrb   = wr ? s : 4'd0;
            psel    = 1'b1;
            penable = 1'b0;
            #1;
            chk_bus(32'd0);
            chk_err(1'b0);
            @(negedge clk);
            penable = 1'b1;
            #1;
            chk_rdy;
            chk_err(eerr);
            chk_bus(wr ? 32'd0 : erd);
            @(negedge clk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'd0;
            pwdata  = 32'd0;
            pstrb   = 4'd0;
            #1;
            chk_bus(32'd0);
            chk_err(1'b0);
        end
    endtask

    task apb_wr(input [7:0] a, input [31:0] d, input [3:0] s, input eerr);
        begin
            xfer(1'b1, a, d, s, 1'b0, 32'd0, 32'd0, eerr);
        end
    endtask

    task apb_rd(input [7:0] a, input [31:0] erd, input eerr);
        begin
            xfer(1'b0, a, 32'd0, 4'd0, 1'b0, 32'd0, erd, eerr);
        end
    endtask

    task idle(input integer cycles);
        begin
            repeat (cycles) @(negedge clk);
        end
    endtask

    task set_pins(input [31:0] v);
        begin
            @(negedge clk);
            gin = v;
        end
    endtask

    task step_mark;
        begin
            stepno = stepno + 1;
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin
        #1000000;
        failed = failed + 1;
        $error("timeout: simulation did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        stepno  = 0;
        nonce   = {64{8'h00}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {64{8'h00}};

        rstn    = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'd0;
        pwdata  = 32'd0;
        pstrb   = 4'd0;
        gin     = 32'd0;

        // ---------------- Reset values ----------------
        idle(3);
        #1;
        step_mark;
        chk_pins(32'd0, 32'd0);
        chk_irq(1'b0, 1'b0, 1'b0);
        chk_bus(32'd0);
        chk_err(1'b0);
        @(negedge clk);
        rstn = 1'b1;

        apb_rd(A_DATA_OUT, 32'd0, 1'b0);
        apb_rd(A_DIR,      32'd0, 1'b0);
        apb_rd(A_DATA_IN,  32'd0, 1'b0);
        apb_rd(A_RISE,     32'd0, 1'b0);
        apb_rd(A_FALL,     32'd0, 1'b0);
        apb_rd(A_HIGH,     32'd0, 1'b0);
        apb_rd(A_LOW,      32'd0, 1'b0);
        apb_rd(A_EN,       32'd0, 1'b0);
        apb_rd(A_STAT,     32'd0, 1'b0);
        step_mark;
        chk_pins(32'd0, 32'd0);
        chk_irq(1'b0, 1'b0, 1'b0);

        // ---------------- DATA_OUT ----------------
        apb_wr(A_DATA_OUT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_DATA_OUT, 32'hFFFF_FFFF, 1'b0);
        step_mark; chk_pins(32'hFFFF_FFFF, 32'd0);
        apb_wr(A_DATA_OUT, 32'h1234_5678, 4'b0101, 1'b0);
        apb_rd(A_DATA_OUT, 32'hFF34_FF78, 1'b0);
        step_mark; chk_pins(32'hFF34_FF78, 32'd0);
        apb_wr(A_DATA_OUT, 32'h0000_0000, 4'b0000, 1'b0);
        apb_rd(A_DATA_OUT, 32'hFF34_FF78, 1'b0);
        apb_wr(A_DATA_OUT, 32'h0000_AB00, 4'b0010, 1'b0);
        apb_rd(A_DATA_OUT, 32'hFF34_AB78, 1'b0);
        step_mark; chk_pins(32'hFF34_AB78, 32'd0);

        // ---------------- DIR ----------------
        apb_wr(A_DIR, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_DIR, 32'hFFFF_FFFF, 1'b0);
        apb_wr(A_DIR, 32'h0000_003C, 4'b0001, 1'b0);
        apb_rd(A_DIR, 32'hFFFF_FF3C, 1'b0);
        step_mark; chk_pins(32'hFF34_AB78, 32'hFFFF_FF3C);
        apb_wr(A_DIR, 32'h8100_0000, 4'b1000, 1'b0);
        apb_rd(A_DIR, 32'h81FF_FF3C, 1'b0);
        step_mark; chk_pins(32'hFF34_AB78, 32'h81FF_FF3C);

        // ---------------- Detection enables (pins idle low) ----------------
        apb_wr(A_RISE, 32'hFFFF_FFFF, 4'b1100, 1'b0);
        apb_rd(A_RISE, 32'hFFFF_0000, 1'b0);
        apb_wr(A_RISE, 32'h0000_00AA, 4'b0001, 1'b0);
        apb_rd(A_RISE, 32'hFFFF_00AA, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_RISE, 32'h0000_0000, 1'b0);

        apb_wr(A_FALL, 32'h5A5A_5A5A, 4'hF, 1'b0);
        apb_rd(A_FALL, 32'h5A5A_5A5A, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'b0100, 1'b0);
        apb_rd(A_FALL, 32'h5A00_5A5A, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_FALL, 32'h0000_0000, 1'b0);

        apb_wr(A_HIGH, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_HIGH, 32'hFFFF_FFFF, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'b0011, 1'b0);
        apb_rd(A_HIGH, 32'hFFFF_0000, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_HIGH, 32'h0000_0000, 1'b0);

        apb_wr(A_EN, 32'hC3C3_C3C3, 4'hF, 1'b0);
        apb_rd(A_EN, 32'hC3C3_C3C3, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);
        apb_wr(A_EN, 32'h0000_0000, 4'b0011, 1'b0);
        apb_rd(A_EN, 32'hC3C3_0000, 1'b0);
        apb_wr(A_EN, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_EN, 32'h0000_0000, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // LOW: pins are low, so enabled bits set status (masked interrupt).
        apb_wr(A_LOW, 32'hFFFF_FFFF, 4'b0110, 1'b0);
        apb_rd(A_LOW, 32'h00FF_FF00, 1'b0);
        apb_wr(A_LOW, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_LOW, 32'h0000_0000, 1'b0);
        apb_rd(A_STAT, 32'h00FF_FF00, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);

        // Write-1-to-clear of some pending bits only.
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'b0010, 1'b0);
        apb_rd(A_STAT, 32'h00FF_0000, 1'b0);
        apb_wr(A_STAT, 32'h00F0_0000, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h000F_0000, 1'b0);
        apb_wr(A_EN, 32'h0001_0000, 4'hF, 1'b0);
        step_mark; chk_irq(1'b1, 1'b0, 1'b0);
        apb_wr(A_EN, 32'h0000_0001, 4'hF, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);
        apb_wr(A_EN, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---------------- DATA_IN and PSLVERR ----------------
        set_pins(32'hDEAD_BEEF);
        idle(2);
        apb_rd(A_DATA_IN, 32'hDEAD_BEEF, 1'b0);
        apb_wr(A_DATA_IN, 32'h0000_0000, 4'hF, 1'b1);
        apb_rd(A_DATA_IN, 32'hDEAD_BEEF, 1'b0);
        apb_wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_rd(8'h24, 32'd0, 1'b1);
        apb_rd(8'h02, 32'd0, 1'b1);
        apb_wr(8'h01, 32'h0000_0000, 4'hF, 1'b1);
        apb_wr(8'h40, 32'h0000_0000, 4'hF, 1'b1);
        apb_wr(8'h80, 32'h0000_0000, 4'hF, 1'b1);
        apb_wr(8'hC4, 32'h0000_0000, 4'hF, 1'b1);
        apb_rd(8'h40, 32'd0, 1'b1);
        apb_rd(8'h3C, 32'd0, 1'b1);
        apb_wr(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_rd(8'hFC, 32'd0, 1'b1);
        apb_wr(8'h0D, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h22, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_rd(A_DATA_OUT, 32'hFF34_AB78, 1'b0);
        apb_rd(A_DIR,      32'h81FF_FF3C, 1'b0);
        apb_rd(A_RISE,     32'h0000_0000, 1'b0);
        step_mark; chk_pins(32'hFF34_AB78, 32'h81FF_FF3C);
        set_pins(32'h0000_0000);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---------------- Rising edge, exact timing, fires once ----------------
        apb_wr(A_RISE, 32'h0000_0003, 4'hF, 1'b0);
        apb_wr(A_EN,   32'h0000_0001, 4'hF, 1'b0);
        // Pin 0 rises before edge E (setup); during access (after E) the
        // status is not yet set; it is set on E + 1.
        xfer(1'b0, A_STAT, 32'd0, 4'd0, 1'b1, 32'h0000_0001, 32'h0000_0000, 1'b0);
        step_mark; chk_irq(1'b1, 1'b1, 1'b1);
        apb_rd(A_STAT, 32'h0000_0001, 1'b0);
        // A pin change before E reads in DATA_IN right after E.
        xfer(1'b0, A_DATA_IN, 32'd0, 4'd0, 1'b1, 32'h0000_0005, 32'h0000_0005, 1'b0);
        apb_wr(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);

        // ---------------- Clear on the edge of a new rising edge ----------------
        set_pins(32'h0000_0007);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0002, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);
        set_pins(32'h0000_0005);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0002, 1'b0);
        xfer(1'b1, A_STAT, 32'h0000_0002, 4'hF, 1'b1, 32'h0000_0007, 32'd0, 1'b0);
        apb_rd(A_STAT, 32'h0000_0002, 1'b0);
        apb_wr(A_STAT, 32'h0000_0002, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---------------- Falling edge and the interrupt mask ----------------
        apb_wr(A_FALL, 32'h0000_0004, 4'hF, 1'b0);
        set_pins(32'h0000_0003);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0004, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);
        apb_wr(A_EN, 32'h0000_0004, 4'hF, 1'b0);
        step_mark; chk_irq(1'b1, 1'b1, 1'b0);
        apb_rd(A_EN, 32'h0000_0004, 1'b0);
        apb_wr(A_STAT, 32'h0000_0004, 4'hF, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);

        // ---------------- High level: sets again after a clear ----------------
        apb_wr(A_HIGH, 32'h0010_0001, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0001, 1'b0);
        set_pins(32'h0010_0003);
        idle(3);
        apb_rd(A_STAT, 32'h0010_0001, 1'b0);
        apb_wr(A_STAT, 32'h0010_0001, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0010_0001, 1'b0);
        set_pins(32'h0010_0002);
        idle(3);
        apb_wr(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0010_0000, 1'b0);
        apb_wr(A_EN, 32'h0010_0000, 4'hF, 1'b0);
        step_mark; chk_irq(1'b1, 1'b0, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        step_mark; chk_irq(1'b0, 1'b0, 1'b0);

        // ---------------- Low level: sets again after a clear ----------------
        apb_wr(A_LOW, 32'h0000_0008, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0008, 1'b0);
        apb_wr(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0008, 1'b0);
        set_pins(32'h0010_000A);
        idle(3);
        apb_wr(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        apb_wr(A_LOW, 32'h0000_0000, 4'hF, 1'b0);

        // ---------------- Reset again ----------------
        apb_wr(A_HIGH, 32'h0000_0002, 4'hF, 1'b0);
        apb_wr(A_EN,   32'h0000_0002, 4'hF, 1'b0);
        step_mark; chk_irq(1'b1, 1'b1, 1'b0);
        @(negedge clk);
        rstn = 1'b0;
        idle(2);
        #1;
        step_mark;
        chk_pins(32'd0, 32'd0);
        chk_irq(1'b0, 1'b0, 1'b0);
        chk_bus(32'd0);
        chk_err(1'b0);
        @(negedge clk);
        rstn = 1'b1;
        apb_rd(A_DATA_OUT, 32'd0, 1'b0);
        apb_rd(A_DIR,      32'd0, 1'b0);
        apb_rd(A_RISE,     32'd0, 1'b0);
        apb_rd(A_FALL,     32'd0, 1'b0);
        apb_rd(A_HIGH,     32'd0, 1'b0);
        apb_rd(A_LOW,      32'd0, 1'b0);
        apb_rd(A_EN,       32'd0, 1'b0);
        apb_rd(A_STAT,     32'd0, 1'b0);
        apb_rd(A_DATA_IN,  32'h0010_000A, 1'b0);
        step_mark;
        chk_pins(32'd0, 32'd0);
        chk_irq(1'b0, 1'b0, 1'b0);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
